import{_ as e,o,c as n,ae as s}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"Design System 與半自動化 UI","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/design-system.md","filePath":"architecture/design-system.md"}'),a={name:"architecture/design-system.md"};function r(i,t,d,c,l,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="design-system-與半自動化-ui" tabindex="-1">Design System 與半自動化 UI <a class="header-anchor" href="#design-system-與半自動化-ui" aria-label="Permalink to &quot;Design System 與半自動化 UI&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本專案朝向 <strong>逐漸建立 Design System</strong>，並以 <strong>半自動化 UI 處理</strong> 維持一致性與可維護性：單一來源的設計 token、元件層與使用規範，未來可搭配工具（如元件目錄、lint 規則）減少手動重複。</p><hr><h2 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to &quot;目標&quot;">​</a></h2><ul><li><strong>單一來源</strong>：顏色、間距、元件 API 以 <a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a> 與 <code>app/components/ui/*</code> 為準。<strong>Token canonical 在 repo</strong>（見 DESIGN_SYSTEM.md「Token Source of Truth」）；Figma 為設計參考，同步規則見 <a href="./figma-mcp.html">figma-mcp</a>。</li><li><strong>漸進建立</strong>：先穩固 core 元件與 tokens，再擴充語義元件與複合元件；不追求一次到位。</li><li><strong>半自動化</strong>：透過規範與約定減少 ad-hoc 樣式；後續可引入元件文件站、ESLint 規則（如偏好 design system 元件）等。</li></ul><hr><h2 id="分層結構-與-docs-design-system-md-對齊" tabindex="-1">分層結構（與 docs/DESIGN_SYSTEM.md 對齊） <a class="header-anchor" href="#分層結構-與-docs-design-system-md-對齊" aria-label="Permalink to &quot;分層結構（與 docs/DESIGN_SYSTEM.md 對齊）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層級</th><th>路徑</th><th>說明</th></tr></thead><tbody><tr><td><strong>Design Tokens</strong></td><td><code>app/tailwind.css</code>、Tailwind config</td><td>brand、semantic、border 等；頁面與元件使用 token，不寫魔術數字</td></tr><tr><td><strong>Core / UI 元件</strong></td><td><code>app/components/ui/*</code></td><td>最小顆粒、以 cva 定義 variants（Button、Input、Card、Alert 等）</td></tr><tr><td><strong>語義 / 領域元件</strong></td><td><code>app/components/shared/lui/*</code> 等</td><td>基於 UI 元件的語義組合（如 ChatBubble）</td></tr><tr><td><strong>複合元件</strong></td><td><code>app/components/shared/chat/*</code> 等</td><td>組合多個 UI + 語義元件（如 ChatInterface）</td></tr><tr><td><strong>頁面</strong></td><td><code>app/routes/*</code></td><td>使用 Container / Card 等約定，透過 variant API 調整樣式</td></tr></tbody></table><hr><h2 id="骨架-vs-視覺-ui-kit" tabindex="-1">骨架 vs 視覺／UI kit <a class="header-anchor" href="#骨架-vs-視覺-ui-kit" aria-label="Permalink to &quot;骨架 vs 視覺／UI kit&quot;">​</a></h2><p>為預留 <strong>UI kit 可換、骨架不換</strong> 的擴充：</p><ul><li><strong>骨架（Skeleton）</strong>：<code>app/components/ui/*</code>（shadcn primitives）。元件 API、結構、行為與無障礙以此為準；<strong>不隨 UI kit 更換而改動</strong>。</li><li><strong>視覺（Token / 主題）</strong>：<code>app/tailwind.css</code>（目前預設）、預留 <code>app/styles/themes/</code>。顏色、間距、圓角、陰影等數值；換 kit 時改 token 來源或 theme 檔即可。</li><li><strong>Kit 表面（可選）</strong>：<code>app/components/theme/*</code>。僅放與當前 UI kit 強相關的 wrapper 或 variant 擴充；換 kit 時只替換此目錄與 theme 檔，<strong>不改</strong> <code>app/components/ui/*</code>。</li></ul><p>依賴：<code>theme/*</code> 僅能依賴 <code>ui/*</code> 與 shared utils；routes/features 預設使用 <code>ui/*</code>，必要時再用 <code>theme/*</code>。詳見 <code>app/components/theme/README.md</code>、<code>app/styles/themes/README.md</code>。</p><hr><h2 id="半自動化策略-漸進" tabindex="-1">半自動化策略（漸進） <a class="header-anchor" href="#半自動化策略-漸進" aria-label="Permalink to &quot;半自動化策略（漸進）&quot;">​</a></h2><ol><li><strong>現況</strong>：DESIGN_SYSTEM.md 記載 tokens、core 元件、使用準則；<a href="./../conventions/coding-conventions.html">coding-conventions</a> 規定元件檔名 PascalCase、資料夾小寫；程式內使用 <code>variant</code> 與 token class，避免內聯魔術數字。</li><li><strong>規範先行</strong>：新 UI 優先使用 <code>app/components/ui/*</code> 與既有語義元件；大區塊用 Card、行動用 Button、提示用 Alert。</li><li><strong>未來可選</strong>：元件目錄（Storybook 或自建 catalog）、ESLint 規則提醒使用 design system 元件、設計稿與 token 同步流程。Figma 端 design pattern / UI kit 選型見 <a href="./design-pattern-ui-kit.html">design-pattern-ui-kit</a>。</li></ol><hr><h2 id="與乾淨架構的關係" tabindex="-1">與乾淨架構的關係 <a class="header-anchor" href="#與乾淨架構的關係" aria-label="Permalink to &quot;與乾淨架構的關係&quot;">​</a></h2><ul><li><strong>UI 層</strong> 屬乾淨架構最外層；Design System 元件不包含業務邏輯，只負責呈現與可存取性。</li><li><strong>業務規格（docs/product）</strong> 可描述「畫面上需要什麼區塊與行為」，實作時由 routes/components 選用 design system 元件組裝，不背離規格。</li></ul><hr><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>：Design tokens、Core components、Usage guidelines、LUI copy style、Token Source of Truth</li><li><a href="./design-system-references.html">design-system-references</a>：Reference-based 設計系統、外部 UI kit 對照與單一實作層</li><li><a href="./design-pattern-ui-kit.html">design-pattern-ui-kit</a>：Figma UI kit 選型評估、候選對照、導入前驗證</li><li><a href="./figma-mcp.html">figma-mcp</a>：Figma MCP 架構、設計稿與 token 同步、導入順序</li><li><a href="./../conventions/coding-conventions.html">coding-conventions</a>：元件與資料夾命名、lint:filenames</li><li><a href="./../product/overview.html">overview</a>：功能一覽（含 UI 技術棧）</li><li><a href="./clean-architecture.html">clean-architecture</a>：UI 在架構中的位置</li></ul>',23)])])}const p=e(a,[["render",r]]);export{m as __pageData,p as default};
